    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO por D.278-2013 según la edición CEDIJ; cotejo con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CT_OLA7.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA7')
  WHERE ingest_batch = 'OLA7_CT_2023_01' AND id IN ('OLA7_CT_2023_01:CODIGO_TRABAJO:464');
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA7_CT_2023_01' AND revision_pendiente = false AND metadata->>'estado_v' = 'V5';
  IF n <> 877 THEN RAISE EXCEPTION 'postcondición visibles V5 = % (esperado 877)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA7_CT_2023_01' AND es_norma_vigente = true AND NOT (metadata ? 'rol');
  IF n <> 863 THEN RAISE EXCEPTION 'postcondición PRIMARY vigentes = % (esperado 863)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA7_CT_2023_01' AND es_norma_vigente = true AND metadata->>'rol' = 'CONTEXT';
  IF n <> 3 THEN RAISE EXCEPTION 'postcondición CONTEXT vigentes = % (esperado 3)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA7_CT_2023_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 11 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 11)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA7_CT_2023_01' AND es_norma_vigente IS NULL AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT pendientes = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA7_CT_2023_01' AND es_norma_vigente = false AND NOT (metadata ? 'rol');
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición derogados PRIMARY (prohibido) = % (esperado 0)', n; END IF;
  UPDATE public.biblioteca_vectores b SET revision_pendiente = true,
    metadata = b.metadata || jsonb_build_object('sustituido_por_lote', 'OLA7_CT_2023_01', 'sustituido_fecha', '2026-11-24', 'revision_pendiente_motivo', 'Sustituida por HN:CODIGO_TRABAJO V5 (OLA7); oculta, no borrada')
  WHERE b.metadata->>'norm_id' = 'HN_CODIGO_TRABAJO' AND b.id LIKE 'v2trabajo:mayalex_normativos:%' AND b.revision_pendiente = false;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 870 THEN RAISE EXCEPTION 'legacy ocultadas: % (esperadas 870)', n; END IF;
